-- AP Control — PostgreSQL schema (cloud / Neon target).
-- Mirrors src/db/schema.sql (SQLite) with Postgres dialect:
--   * INTEGER PRIMARY KEY AUTOINCREMENT  -> GENERATED BY DEFAULT AS IDENTITY
--   * money columns are BIGINT agorot (64-bit, matches SQLite INTEGER)
--   * timestamp defaults use to_char(now()) to keep the 'YYYY-MM-DD HH:MM:SS' text format
--   * tables are ordered so every FK target exists first (Postgres validates FKs at create time)
-- Amounts are agorot; dates 'YYYY-MM-DD'; timestamps 'YYYY-MM-DD HH:MM:SS' (UTC).

-- companies ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS companies (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name         TEXT NOT NULL,
  company_type TEXT,
  tax_id       TEXT
);

-- users -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          TEXT NOT NULL,
  role          TEXT NOT NULL CHECK (role IN ('owner','secretary')),
  username      TEXT,
  email         TEXT,
  password_hash TEXT
);
ALTER TABLE users ADD COLUMN IF NOT EXISTS email TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS label TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS permissions TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS must_change_password INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS login_start TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS login_end   TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS ux_users_username ON users(username) WHERE username IS NOT NULL;

-- Per-user company access (הפרדת חברות). Non-owner sees ONLY listed companies; owner sees all.
CREATE TABLE IF NOT EXISTS user_companies (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  UNIQUE (user_id, company_id)
);

-- Password-reset tokens (email flow). Only a SHA-256 hash of the token is stored.
CREATE TABLE IF NOT EXISTS password_resets (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id),
  token_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at    TEXT
);
CREATE INDEX IF NOT EXISTS ix_password_resets_token ON password_resets(token_hash);

-- Calendar events / reminders for the "יומן" page.
CREATE TABLE IF NOT EXISTS calendar_events (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title       TEXT NOT NULL,
  event_date  TEXT NOT NULL,
  event_time  TEXT,
  remind      INTEGER NOT NULL DEFAULT 0,
  remind_sent INTEGER NOT NULL DEFAULT 0,
  created_by  INTEGER REFERENCES users(id)
);
CREATE INDEX IF NOT EXISTS ix_calendar_events_date ON calendar_events(event_date);

-- Approval workflow: edits by non-owners queued for the owner.
CREATE TABLE IF NOT EXISTS change_requests (
  id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  requested_by      INTEGER REFERENCES users(id),
  requested_by_name TEXT,
  action            TEXT NOT NULL,
  entity_type       TEXT,
  entity_id         INTEGER,
  payload           TEXT NOT NULL,
  summary           TEXT,
  status            TEXT NOT NULL DEFAULT 'pending',
  decided_by        INTEGER,
  decided_at        TEXT,
  decision_note     TEXT,
  result_summary    TEXT,
  created_at        TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_change_requests_status ON change_requests(status);

-- In-app notification stream (bell + /notifications). Mirrors the Telegram alerts.
CREATE TABLE IF NOT EXISTS notifications (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind       TEXT NOT NULL DEFAULT 'alert',
  title      TEXT NOT NULL,
  body       TEXT,
  link       TEXT,
  created_at TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
  read_at    TEXT
);
CREATE INDEX IF NOT EXISTS ix_notifications_created ON notifications(created_at);

-- stores ------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stores (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  name       TEXT NOT NULL,
  address    TEXT
);

-- Per-user store access (הרשאה פר-חנות) — defined after stores so the FK validates. See schema.sql.
CREATE TABLE IF NOT EXISTS user_stores (
  id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id  INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  store_id INTEGER NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (user_id, store_id)
);

-- bank_accounts — 1:1 with a store ----------------------------------------------
CREATE TABLE IF NOT EXISTS bank_accounts (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id     INTEGER NOT NULL REFERENCES companies(id),
  store_id       INTEGER NOT NULL UNIQUE REFERENCES stores(id),
  bank_name      TEXT NOT NULL DEFAULT 'הפועלים',
  branch         TEXT NOT NULL,
  account_number TEXT NOT NULL,
  display_name   TEXT NOT NULL
);

-- suppliers ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS suppliers (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL,
  tax_id      TEXT,
  status      TEXT NOT NULL DEFAULT 'pending'
              CHECK (status IN ('pending','approved','blocked')),
  approved_by INTEGER REFERENCES users(id),
  approved_at TEXT,
  notes       TEXT,
  phone          TEXT,
  email          TEXT,
  contact_name   TEXT,
  contact_phone  TEXT,
  payment_method TEXT,
  payment_terms  TEXT,
  scan_profile   TEXT,  -- "הסקיל": מבנה החשבונית של הספק, נלמד מהסריקות שלו (JSON)
  parent_supplier_id INTEGER REFERENCES suppliers(id)  -- תשלום מרוכז: חברת-בת מצביעה לחברת-האם
);
-- migrations for existing databases (idempotent)
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS payment_method TEXT;
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS payment_terms  TEXT;
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS scan_profile   TEXT;
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS parent_supplier_id INTEGER REFERENCES suppliers(id);

-- Which stores a supplier serves (many-to-many). stores is defined above, so the FK validates.
CREATE TABLE IF NOT EXISTS supplier_stores (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,
  store_id    INTEGER NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (supplier_id, store_id)
);
CREATE INDEX IF NOT EXISTS ix_supplier_stores_supplier ON supplier_stores(supplier_id);

-- invoices ----------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invoices (
  id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id        INTEGER NOT NULL REFERENCES suppliers(id),
  company_id         INTEGER NOT NULL REFERENCES companies(id),
  store_id           INTEGER NOT NULL REFERENCES stores(id),
  bank_account_id    INTEGER REFERENCES bank_accounts(id),
  invoice_number     TEXT NOT NULL,
  allocation_number  TEXT,
  invoice_date       TEXT NOT NULL,
  amount_before_vat  BIGINT NOT NULL,
  vat_amount         BIGINT NOT NULL DEFAULT 0,
  total_amount       BIGINT NOT NULL,
  doc_type           TEXT NOT NULL
                     CHECK (doc_type IN ('tax_invoice','tax_invoice_receipt','credit_note')),
  image_path         TEXT,
  status             TEXT NOT NULL DEFAULT 'recorded'
                     CHECK (status IN ('recorded','approved_for_payment','on_hold','paid')),
  hold_reason        TEXT,
  created_by         INTEGER NOT NULL REFERENCES users(id),
  created_at         TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoices_allocation
  ON invoices(allocation_number) WHERE allocation_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_invoices_supplier_number
  ON invoices(supplier_id, invoice_number);

-- payments ----------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payments (
  id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_account_id INTEGER NOT NULL REFERENCES bank_accounts(id),
  method          TEXT NOT NULL DEFAULT 'check'
                  CHECK (method IN ('check','cash','credit','transfer','batch','standing_order')),
  check_number    TEXT,
  reference       TEXT,
  payer_name      TEXT,
  card_last4      TEXT,
  batch_number    TEXT,
  payment_date    TEXT NOT NULL,
  amount          BIGINT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'issued'
                  CHECK (status IN ('issued','cleared','voided')),
  cleared_date    TEXT,
  created_by      INTEGER NOT NULL REFERENCES users(id),
  created_at      TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_payments_account_check
  ON payments(bank_account_id, check_number) WHERE check_number IS NOT NULL AND status <> 'voided';

-- payment_lines -----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS payment_lines (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_id     INTEGER NOT NULL REFERENCES payments(id) ON DELETE CASCADE,
  invoice_id     INTEGER NOT NULL REFERENCES invoices(id),
  amount_applied BIGINT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_payment_lines_invoice
  ON payment_lines(payment_id, invoice_id);

-- bank_transactions -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS bank_transactions (
  id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bank_account_id    INTEGER NOT NULL REFERENCES bank_accounts(id),
  txn_date           TEXT NOT NULL,
  amount             BIGINT NOT NULL,
  description        TEXT,
  raw_reference      TEXT,
  balance_after      BIGINT,
  source             TEXT NOT NULL DEFAULT 'scraper',
  matched_payment_id INTEGER REFERENCES payments(id)
);
ALTER TABLE bank_transactions ADD COLUMN IF NOT EXISTS balance_after BIGINT;

-- invoice_ocr -------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invoice_ocr (
  invoice_id INTEGER PRIMARY KEY REFERENCES invoices(id) ON DELETE CASCADE,
  raw_text   TEXT,
  extracted  TEXT,
  provider   TEXT,
  ran_at     TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

-- z_reports ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS z_reports (
  id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store_id         INTEGER NOT NULL REFERENCES stores(id),
  z_number         TEXT NOT NULL,
  z_date           TEXT NOT NULL,
  daily_total      BIGINT NOT NULL DEFAULT 0,
  drawer_cash      BIGINT NOT NULL DEFAULT 0,
  drawer_check     BIGINT NOT NULL DEFAULT 0,
  drawer_credit    BIGINT NOT NULL DEFAULT 0,
  drawer_hakafa    BIGINT NOT NULL DEFAULT 0,
  drawer_vouchers  BIGINT NOT NULL DEFAULT 0,
  drawer_total     BIGINT NOT NULL DEFAULT 0,
  deposit_amount   BIGINT,
  deposit_bag      TEXT,
  deposit_breakdown TEXT,
  cc_kal BIGINT, cc_isracard BIGINT, cc_diners BIGINT, cc_amex BIGINT,
  cc_general BIGINT, cc_tourist BIGINT, cc_total BIGINT,
  status           TEXT NOT NULL DEFAULT 'ok' CHECK (status IN ('ok','unmatched')),
  reconcile_notes  TEXT,
  created_by       INTEGER NOT NULL REFERENCES users(id),
  created_at       TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS ix_zreports_store_date ON z_reports(store_id, z_date);

-- employees — staff for "עובדים ומשכורות"; advances/salary lines on a Z reference an employee.
CREATE TABLE IF NOT EXISTS employees (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name  TEXT NOT NULL,
  last_name   TEXT NOT NULL,
  phone       TEXT,
  active      INTEGER NOT NULL DEFAULT 1,
  created_by  INTEGER REFERENCES users(id),
  created_at  TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

-- z_expenses --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS z_expenses (
  id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  z_report_id      INTEGER NOT NULL REFERENCES z_reports(id) ON DELETE CASCADE,
  expense_date     TEXT,
  payer_name       TEXT,
  description_type TEXT,
  employee_name    TEXT,
  amount           BIGINT NOT NULL DEFAULT 0,
  image_path       TEXT,
  created_at       TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

-- deposits — bank deposit declaration (bag number + amount + deposited flag)
CREATE TABLE IF NOT EXISTS deposits (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store_id     INTEGER NOT NULL REFERENCES stores(id),
  deposit_date TEXT NOT NULL,
  bag_number   TEXT,
  amount       BIGINT NOT NULL DEFAULT 0,
  deposited    INTEGER NOT NULL DEFAULT 0,
  created_by   INTEGER NOT NULL REFERENCES users(id),
  created_at   TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

-- z_closings — register-closer end-of-shift cash count (see schema.sql for details).
CREATE TABLE IF NOT EXISTS z_closings (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_first TEXT NOT NULL,
  employee_last  TEXT NOT NULL,
  store_id       INTEGER REFERENCES stores(id),
  z_number       TEXT,
  drawer_cash    BIGINT NOT NULL DEFAULT 0,
  started_at     TEXT,
  ended_at       TEXT,
  breakdown      TEXT,
  total_cash     BIGINT NOT NULL DEFAULT 0,
  expenses       TEXT,
  total_expenses BIGINT NOT NULL DEFAULT 0,
  grand_total    BIGINT NOT NULL DEFAULT 0,
  created_by     INTEGER REFERENCES users(id),
  created_at     TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);

-- sales_entries -----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sales_entries (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store_id   INTEGER NOT NULL REFERENCES stores(id),
  sale_date  TEXT NOT NULL,
  amount     BIGINT NOT NULL,
  notes      TEXT,
  created_by INTEGER NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS ix_sales_store_date ON sales_entries(store_id, sale_date);

-- audit_log ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_log (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id     INTEGER REFERENCES users(id),
  action      TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id   INTEGER,
  timestamp   TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
  details     TEXT
);

-- Saved role templates: a named permission preset the owner can apply to a user in one click.
CREATE TABLE IF NOT EXISTS role_templates (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        TEXT NOT NULL,
  permissions TEXT,
  created_at  TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_role_templates_name ON role_templates(name);

-- Cash-expense "purpose" (עבור) + a scan of the Z slip itself.
ALTER TABLE z_expenses ADD COLUMN IF NOT EXISTS purpose TEXT;
ALTER TABLE z_reports  ADD COLUMN IF NOT EXISTS image_path TEXT;

-- Cash expense matched to an invoice; deposit → Z link + bank reconciliation (bag=reference).
ALTER TABLE z_expenses ADD COLUMN IF NOT EXISTS invoice_id     INTEGER REFERENCES invoices(id);
ALTER TABLE deposits   ADD COLUMN IF NOT EXISTS z_report_id    INTEGER REFERENCES z_reports(id);
ALTER TABLE deposits   ADD COLUMN IF NOT EXISTS matched_txn_id INTEGER REFERENCES bank_transactions(id);
ALTER TABLE deposits   ADD COLUMN IF NOT EXISTS recon_diff     BIGINT;

-- Z edit timestamp (last edited date+time).
ALTER TABLE z_reports  ADD COLUMN IF NOT EXISTS updated_at TEXT;
-- Manager's bill recount vs the Z closing (JSON {denom:{count,ok}}).
ALTER TABLE z_reports  ADD COLUMN IF NOT EXISTS manager_breakdown TEXT;

-- Register-closing: which store + Z number + declared drawer cash.
ALTER TABLE z_closings ADD COLUMN IF NOT EXISTS store_id    INTEGER REFERENCES stores(id);
ALTER TABLE z_closings ADD COLUMN IF NOT EXISTS z_number    TEXT;
ALTER TABLE z_closings ADD COLUMN IF NOT EXISTS drawer_cash BIGINT NOT NULL DEFAULT 0;

-- Cash expense → employee link (salary/advance lines feed the employees tracking table).
ALTER TABLE z_expenses ADD COLUMN IF NOT EXISTS employee_id INTEGER REFERENCES employees(id);

-- Optional employee phone (used to dedupe an Excel import of the staff list).
ALTER TABLE employees ADD COLUMN IF NOT EXISTS phone TEXT;

-- products — קטלוג מוצרים מצטבר לפי ספק (נבנה מאישור חשבוניות סרוקות). last_cost הוא מחיר
-- היחידה האחרון שנקלט (אגורות, לפני מע"מ) יחד עם תאריך החשבונית שקבע אותו.
CREATE TABLE IF NOT EXISTS products (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id    INTEGER NOT NULL REFERENCES suppliers(id),
  name           TEXT NOT NULL,
  barcode        TEXT,
  sku            TEXT,
  last_cost      BIGINT,
  last_cost_date TEXT,
  created_at     TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
  updated_at     TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_products_supplier_barcode
  ON products(supplier_id, barcode) WHERE barcode IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_products_supplier_name ON products(supplier_id, name);

-- product_prices — היסטוריית מחירי קנייה למוצר (שורה לכל חשבונית שבה הופיע).
CREATE TABLE IF NOT EXISTS product_prices (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  invoice_id INTEGER REFERENCES invoices(id),
  price      BIGINT NOT NULL,
  quantity   DOUBLE PRECISION,
  price_date TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS ix_product_prices_product_date
  ON product_prices(product_id, price_date);

-- invoice_lines — שורות הפריטים של חשבונית (agorot לפני מע"מ; שלילי בחשבונית זיכוי).
CREATE TABLE IF NOT EXISTS invoice_lines (
  id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_id       INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  product_id       INTEGER REFERENCES products(id),
  line_no          INTEGER NOT NULL,
  name             TEXT NOT NULL,
  barcode          TEXT,
  sku              TEXT,
  quantity         DOUBLE PRECISION NOT NULL DEFAULT 1,  -- כמות כפי שמודפסת (לעיתים ארגזים)
  unit_quantity    DOUBLE PRECISION,                      -- כ.בודד: מספר היחידות הבודדות בשורה
  unit_cost        BIGINT,                                -- agorot ליחידה בודדת
  unit_cost_source TEXT
                   CHECK (unit_cost_source IN ('extracted','computed','manual')),
  pack_cost        BIGINT,                                -- agorot לארגז/מארז כשהמחיר המודפס אינו ליחידה
  line_total       BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_invoice_lines_invoice ON invoice_lines(invoice_id);
-- migrations for existing databases (idempotent) — CREATE TABLE IF NOT EXISTS above is a
-- no-op once the table exists, so every new column needs an explicit ALTER here.
ALTER TABLE invoice_lines ADD COLUMN IF NOT EXISTS unit_quantity DOUBLE PRECISION;
ALTER TABLE invoice_lines ADD COLUMN IF NOT EXISTS pack_cost     BIGINT;

-- invoice_drafts — טיוטת חשבונית סרוקה (תמונות + חילוץ המודל) עד לאישור העובד.
CREATE TABLE IF NOT EXISTS invoice_drafts (
  id                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store_id              INTEGER NOT NULL REFERENCES stores(id),
  company_id            INTEGER NOT NULL REFERENCES companies(id),
  supplier_id           INTEGER REFERENCES suppliers(id),   -- נבחר במסך הצילום, כדי שהסקיל ייסע עם הצילום הראשון
  status                TEXT NOT NULL DEFAULT 'uploaded'
                        CHECK (status IN ('uploaded','processing','needs_review','committed','failed')),
  images                TEXT NOT NULL,
  extraction            TEXT,
  normalized            TEXT,
  error                 TEXT,
  model                 TEXT,
  input_tokens          INTEGER,
  output_tokens         INTEGER,
  duration_ms           INTEGER,
  invoice_id            INTEGER REFERENCES invoices(id),
  processing_started_at TEXT,
  created_by            INTEGER NOT NULL REFERENCES users(id),
  created_at            TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
  updated_at            TEXT
);
ALTER TABLE invoice_drafts ADD COLUMN IF NOT EXISTS supplier_id INTEGER REFERENCES suppliers(id);
CREATE INDEX IF NOT EXISTS ix_invoice_drafts_status ON invoice_drafts(status);

-- master_catalog — קטלוג-על (ראו schema.sql): זהות מוצר לפי ברקוד; retail_price לתצוגה בלבד.
CREATE TABLE IF NOT EXISTS master_catalog (
  id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  barcode           TEXT NOT NULL UNIQUE,
  name              TEXT NOT NULL,
  sku               TEXT,
  manufacturer_name TEXT,
  manufacturer_norm TEXT,
  unit_qty          TEXT,
  quantity          DOUBLE PRECISION,
  qty_in_package    DOUBLE PRECISION,
  retail_price      BIGINT,
  source_chain      TEXT NOT NULL DEFAULT 'shufersal',
  source_store      TEXT,
  imported_at       TEXT NOT NULL,
  created_at        TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS ix_master_catalog_manufacturer ON master_catalog(manufacturer_norm);
-- קטלוג-על: מק"ט (נוסף אחרי שהטבלה כבר קיימת אצל חלק מההתקנות)
ALTER TABLE master_catalog ADD COLUMN IF NOT EXISTS sku TEXT;

-- Allow the 'standing_order' (הו"ק) payment method on existing databases: replace the method
-- CHECK constraint (PG names an inline column CHECK '<table>_<column>_check').
ALTER TABLE payments DROP CONSTRAINT IF EXISTS payments_method_check;
ALTER TABLE payments ADD CONSTRAINT payments_method_check
  CHECK (method IN ('check','cash','credit','transfer','batch','standing_order'));

-- z_closing_expenses — itemized cash expenses of a register closing (סגירת Z), same shape as
-- z_expenses: kind (manual/salary/advance/invoice), date, payer/purpose, employee/invoice link.
CREATE TABLE IF NOT EXISTS z_closing_expenses (
  id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  closing_id       INTEGER NOT NULL REFERENCES z_closings(id) ON DELETE CASCADE,
  expense_date     TEXT,
  payer_name       TEXT,
  purpose          TEXT,
  description_type TEXT,             -- kind: manual / salary / advance / invoice
  employee_id      INTEGER REFERENCES employees(id),
  invoice_id       INTEGER REFERENCES invoices(id),
  amount           BIGINT NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS ix_z_closing_expenses_closing ON z_closing_expenses(closing_id);
CREATE INDEX IF NOT EXISTS ix_z_closing_expenses_invoice ON z_closing_expenses(invoice_id);

-- Register closing: who performed the count (link to the employees list, replacing free text).
ALTER TABLE z_closings ADD COLUMN IF NOT EXISTS employee_id INTEGER REFERENCES employees(id);
-- Per-register cash balancing (JSON) counted before the Z.
ALTER TABLE z_closings ADD COLUMN IF NOT EXISTS registers TEXT;

-- A voided check must release its number so a corrected check can reuse it. Rebuild the unique
-- index to exclude voided payments (the old index blocked reissuing a voided check's number).
DROP INDEX IF EXISTS ux_payments_account_check;
CREATE UNIQUE INDEX IF NOT EXISTS ux_payments_account_check
  ON payments(bank_account_id, check_number) WHERE check_number IS NOT NULL AND status <> 'voided';

-- app_settings — app-wide key/value flags (entitlements/toggles), e.g. scan feature lock.
CREATE TABLE IF NOT EXISTS app_settings (
  key        TEXT PRIMARY KEY,
  value      TEXT,
  updated_at TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
);
-- supplier_catalog — הקטלוג של הספק עצמו (ראו schema.sql): זיהוי מוצר בחשבונית ללא ברקוד.
CREATE TABLE IF NOT EXISTS supplier_catalog (
  id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  supplier_id     INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,
  barcode         TEXT NOT NULL,
  name            TEXT NOT NULL,
  name_norm       TEXT NOT NULL,
  sku             TEXT,
  pack_type       TEXT,
  pack_units      INTEGER,
  brand           TEXT,
  category        TEXT,
  linked_barcode  TEXT,
  imported_at     TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (supplier_id, barcode)
);
CREATE INDEX IF NOT EXISTS ix_supplier_catalog_supplier ON supplier_catalog(supplier_id);
